  const head = which => `${reviewer() ? `<div class="pt-seg">${[['appts', 'Appointments', 'ri-calendar-line'], ['reviews', `Reviews${dnaQueue().length ? ` <span class="pt-tab-n">${dnaQueue().length}</span>` : ''}`, 'ri-file-search-line']].map(([k, t, i]) => `<button class="${v.tab === k ? 'on' : ''}" data-act="ap-tab" data-v="${k}"><i class="${i}"></i>${t}</button>`).join('')}</div>` : ''}
    ${reviewer() && v.tab === 'appts' && dnaQueue().length ? attention() : ''}
    <div class="pt-bar"><h1 class="h6 hh1" style="margin:0">Appointments</h1><span class="grow"></span><div class="pt-seg">${[['cal', 'Calendar View', 'ri-calendar-line', '#/appointments'], ['tbl', 'Table View', 'ri-table-line', '#/appointments/table']].map(([k, t, i, h]) => `<button class="${which === k ? 'on' : ''}" data-go="${h}"><i class="${i}"></i>${t}</button>`).join('')}</div><button class="btn primary lg" data-act="ap-book"><i class="ri-add-circle-line"></i>Book Appointment</button></div>`;
